//! Cookers for the renderer's generated data.
//!
//! - [`PairingPatternCooker`]: ReSTIR's pairing patterns (`marlin_render::asset::pairing`,
//!   0010 §2.5), generated by [`generate_pairing`].

use marlin_asset::cooked::Encoding;
use marlin_cook_core::{CookContext, Cooked, Cooker, SourceObject};
use marlin_math::Rng;
use marlin_reflect::type_info;
use marlin_render::asset::PairingPattern;
use marlin_render::asset::pairing::{
    CookedPairingPattern, MAX_PATTERN_SIZE, MAX_PATTERNS, pack_offset,
};
use marlin_serial::cooked::{CookedBuilder, RelSlice};

/// A `size` × `size` pairing pattern (PTE §3.1): every pixel paired with one other, the
/// offsets between partners about normally distributed with deviation `sigma` per axis, wrapped
/// around the pattern. Returns the packed offsets, row-major (`pack_offset`).
///
/// Starts from horizontal neighbors paired, then shuffles the pixels of the 2×2 blocks of a
/// random grid alignment, again and again, carrying the pairs along: every shuffle moves each
/// pixel at most one step per axis, so the offsets random-walk towards a normal distribution, and
/// a pair stays a pair. Stops once the mean squared offset reaches `2σ²`.
///
/// `size` is even and at most `MAX_PATTERN_SIZE`.
pub fn generate_pairing(size: u32, sigma: f32, rng: &mut Rng) -> Vec<u16> {
    assert!((2..=MAX_PATTERN_SIZE).contains(&size) && size.is_multiple_of(2));
    let n = size as usize;
    let count = n * n;
    let target = 2.0 * f64::from(sigma) * f64::from(sigma);
    loop {
        // The partner of the pixel at `p` and the offset to it, unwrapped.
        let mut partner: Vec<u32> = (0..count as u32).map(|i| i ^ 1).collect();
        let mut offset: Vec<(i32, i32)> = (0..count)
            .map(|i| if i % 2 == 0 { (1, 0) } else { (-1, 0) })
            .collect();
        let mut to = vec![0u32; count];
        let mut step = vec![(0i32, 0i32); count];
        let (mut next_partner, mut next_offset) = (partner.clone(), offset.clone());
        let mean_square = |offset: &[(i32, i32)]| {
            offset
                .iter()
                .map(|&(dx, dy)| f64::from(dx * dx + dy * dy))
                .sum::<f64>()
                / count as f64
        };
        while mean_square(&offset) < target {
            let (ox, oy) = (rng.below(2), rng.below(2));
            for by in 0..n / 2 {
                for bx in 0..n / 2 {
                    let mut order = [0usize, 1, 2, 3];
                    rng.shuffle(&mut order);
                    for (from, &into) in order.iter().enumerate() {
                        let (fx, fy) = (from % 2, from / 2);
                        let (tx, ty) = (into % 2, into / 2);
                        let at = |i: usize, j: usize| {
                            ((oy + 2 * by + j) % n) * n + (ox + 2 * bx + i) % n
                        };
                        let p = at(fx, fy);
                        to[p] = at(tx, ty) as u32;
                        step[p] = (tx as i32 - fx as i32, ty as i32 - fy as i32);
                    }
                }
            }
            // The pixel at `p` moves to `to[p]`, its partner with it.
            for p in 0..count {
                let q = partner[p] as usize;
                let at = to[p] as usize;
                next_partner[at] = to[q];
                next_offset[at] = (
                    offset[p].0 + step[q].0 - step[p].0,
                    offset[p].1 + step[q].1 - step[p].1,
                );
            }
            core::mem::swap(&mut partner, &mut next_partner);
            core::mem::swap(&mut offset, &mut next_offset);
        }
        // An offset past 8 bits is some 8σ out: never at the patterns' σ, but start over then.
        if offset
            .iter()
            .all(|&(dx, dy)| (-128..128).contains(&dx) && (-128..128).contains(&dy))
        {
            return offset.iter().map(|&(dx, dy)| pack_offset(dx, dy)).collect();
        }
    }
}

/// The deviation per axis whose mean distance is a disk of radius `radius`'s: `σ√(π/2) = 2r/3`.
pub fn pairing_sigma(radius: f32) -> f32 {
    2.0 * radius / (3.0 * (core::f32::consts::PI / 2.0).sqrt())
}

/// A cooked [`PairingPattern`] payload (`CookedPairingPattern`).
pub fn cook_pairing(pattern: &PairingPattern) -> Result<Vec<u8>, String> {
    if pattern.sizes.is_empty() || pattern.sizes.len() > MAX_PATTERNS {
        return Err(format!("`Sizes`: 1 to {MAX_PATTERNS} patterns"));
    }
    if let Some(s) = pattern
        .sizes
        .iter()
        .find(|&&s| !(2..=MAX_PATTERN_SIZE).contains(&s) || !s.is_multiple_of(2))
    {
        return Err(format!(
            "`Sizes`: {s} is not an even side from 2 to {MAX_PATTERN_SIZE}"
        ));
    }
    if !(pattern.radius >= 1.0 && pattern.radius <= 40.0) {
        return Err(format!(
            "`Radius` = {}: from 1 to 40 pixels (offsets fit 8 bits)",
            pattern.radius
        ));
    }
    let sigma = pairing_sigma(pattern.radius);
    let mut rng = Rng::new(pattern.seed);
    let offsets: Vec<u16> = pattern
        .sizes
        .iter()
        .flat_map(|&s| generate_pairing(s, sigma, &mut rng))
        .collect();
    let mut b = CookedBuilder::new();
    let root = b.push(&CookedPairingPattern {
        sizes: RelSlice::EMPTY,
        offsets: RelSlice::EMPTY,
    });
    let sizes = b.push_slice(&pattern.sizes);
    let offsets = b.push_slice(&offsets);
    b.link_slice(
        root.field(core::mem::offset_of!(CookedPairingPattern, sizes), |p| {
            &p.sizes
        }),
        sizes,
    )
    .and_then(|()| {
        b.link_slice(
            root.field(core::mem::offset_of!(CookedPairingPattern, offsets), |p| {
                &p.offsets
            }),
            offsets,
        )
    })
    .map_err(|e| e.to_string())?;
    Ok(b.bytes().to_vec())
}

/// Cooks [`PairingPattern`] objects.
pub struct PairingPatternCooker;

impl Cooker for PairingPatternCooker {
    fn version(&self) -> u32 {
        1
    }

    fn cook(&self, object: &SourceObject<'_>, _: &mut CookContext<'_>) -> Result<Cooked, String> {
        let pattern: &PairingPattern = object
            .value
            .as_ref()
            .downcast()
            .ok_or("the object is not a PairingPattern")?;
        Ok(Cooked {
            type_id: type_info::<PairingPattern>().id,
            encoding: Encoding::Cooked,
            payload: cook_pairing(pattern)?,
        })
    }
}
